export const title = "How to Stop Desk Vibrations From Reaching Your Microphone";
export const metaTitle = "How to Stop Desk Vibrations From Reaching Your";
export const metaDescription = "Trace desk-to-microphone vibration through mounts, arms, cables, and furniture with a practical comparison routine. A research-based guide from DeskFinds.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-11-17";
